import{$ as e,A as t,B as n,V as r}from"./chunks/framework.qypF2UUz.js";import"./chunks/assets.BzCF-dV2.js";var i=JSON.parse(`{"title":"Web 管理后台","description":"","frontmatter":{"prev":{"text":"工具概述","link":"/tools/overview"},"next":{"text":"API 参考","link":"/api/reference"}},"headers":[],"relativePath":"tools/webadmin.md","filePath":"tools/webadmin.md","lastUpdated":1786190638000}`),a={name:`tools/webadmin.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="web-管理后台" tabindex="-1">Web 管理后台 <a class="header-anchor" href="#web-管理后台" aria-label="Permalink to “Web 管理后台”">​</a></h1><p>StarTraveller 提供一个独立于机器人主进程的 Web 管理后台（<code>webadmin/</code>），用于在浏览器中查看系统状态、管理用户与插件。它基于 Flask 构建，按需读取机器人的数据文件，不修改 <code>client.py</code> / <code>main.py</code> 的运行逻辑。</p><h2 id="功能总览" tabindex="-1">功能总览 <a class="header-anchor" href="#功能总览" aria-label="Permalink to “功能总览”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">页面</th><th style="text-align:left;">功能</th></tr></thead><tbody><tr><td style="text-align:left;">仪表盘</td><td style="text-align:left;">系统概览：用户数、今日签到、积分总量、角色分布、近 14 天签到趋势、访问统计、机器人运行状态</td></tr><tr><td style="text-align:left;">用户管理</td><td style="text-align:left;">查看全部用户（昵称 / 积分 / 连续签到 / 好感度 / 角色），支持搜索与排序</td></tr><tr><td style="text-align:left;">记忆库</td><td style="text-align:left;">检索所有用户的 RAG 对话记忆记录</td></tr><tr><td style="text-align:left;">插件管理</td><td style="text-align:left;">展示已加载插件列表及其触发关键字、帮助信息</td></tr><tr><td style="text-align:left;">定时任务</td><td style="text-align:left;">查看定时群发配置（启用状态 / 发送时间 / 目标频道 / 最近发送日期）</td></tr><tr><td style="text-align:left;">系统设置</td><td style="text-align:left;">查看机器人配置（脱敏展示密钥类字段）与运行信息</td></tr></tbody></table><h2 id="启动方式" tabindex="-1">启动方式 <a class="header-anchor" href="#启动方式" aria-label="Permalink to “启动方式”">​</a></h2><h3 id="随机器人自动启动" tabindex="-1">随机器人自动启动 <a class="header-anchor" href="#随机器人自动启动" aria-label="Permalink to “随机器人自动启动”">​</a></h3><p>在 <code>config.json</code> 中配置 <code>webadmin</code> 段后，<code>main.py</code> 会以<strong>守护线程</strong>方式随机器人同步启动管理后台，不影响机器人事件循环：</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;webadmin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;host&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;port&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8765</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;password&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你的强密码&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="独立启动" tabindex="-1">独立启动 <a class="header-anchor" href="#独立启动" aria-label="Permalink to “独立启动”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> webadmin.server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8765</span></span></code></pre></div><h3 id="配置优先级" tabindex="-1">配置优先级 <a class="header-anchor" href="#配置优先级" aria-label="Permalink to “配置优先级”">​</a></h3><ol><li>启动参数（<code>--host</code> / <code>--port</code> / <code>--password</code>）</li><li>环境变量 <code>STAR_TRAVELLER_ADMIN_HOST</code> / <code>_PORT</code> / <code>_PASSWORD</code></li><li><code>config.json</code> 的 <code>webadmin</code> 段</li><li>内置默认值（<code>0.0.0.0:8765</code>，密码 <code>admin123</code>）</li></ol><blockquote><p><strong>安全提示</strong>：默认监听 <code>0.0.0.0</code>（所有网卡），访问时不校验 Host 头端口，请务必设置强密码，避免使用默认密码 <code>admin123</code>。</p></blockquote><h2 id="访问与登录" tabindex="-1">访问与登录 <a class="header-anchor" href="#访问与登录" aria-label="Permalink to “访问与登录”">​</a></h2><p>启动后访问 <code>http://服务器IP:8765/admin</code>，输入密码即可登录。Token 有效期 7 天，登录接口带速率限制（1 分钟内的失败尝试）。</p><h2 id="界面预览" tabindex="-1">界面预览 <a class="header-anchor" href="#界面预览" aria-label="Permalink to “界面预览”">​</a></h2><h3 id="仪表盘" tabindex="-1">仪表盘 <a class="header-anchor" href="#仪表盘" aria-label="Permalink to “仪表盘”">​</a></h3><p><img src="/webadmin/dashboard.webp" alt="仪表盘"></p><p>仪表盘集中展示机器人运行的核心指标：用户总数、今日签到人数、累计积分、角色数量、RAG 记忆条数、插件数量与访问统计，并绘制近 14 天签到趋势与角色分布图。</p><h3 id="用户管理" tabindex="-1">用户管理 <a class="header-anchor" href="#用户管理" aria-label="Permalink to “用户管理”">​</a></h3><p><img src="/webadmin/users.webp" alt="用户管理"></p><p>用户管理页列出所有签到用户，展示昵称、积分、连续签到天数、好感度与当前角色，支持关键字搜索。</p><p><img src="/webadmin/users-verify.webp" alt="用户核验"></p><p>支持对用户进行核验操作，便于管理群成员状态。</p><h3 id="系统设置" tabindex="-1">系统设置 <a class="header-anchor" href="#系统设置" aria-label="Permalink to “系统设置”">​</a></h3><p><img src="/webadmin/settings-dark.webp" alt="系统设置"></p><p>系统设置页展示机器人配置与运行信息，密钥类字段（密码、Secret、Token、AppID 等）自动脱敏显示，避免敏感信息泄露。</p><h3 id="响应式布局" tabindex="-1">响应式布局 <a class="header-anchor" href="#响应式布局" aria-label="Permalink to “响应式布局”">​</a></h3><p>管理后台适配桌面端与移动端：</p><p><img src="/webadmin/mobile-drawer.webp" alt="移动端抽屉菜单"></p><p><img src="/webadmin/sidebar-collapsed.webp" alt="桌面端侧边栏折叠"></p><h2 id="api-端点" tabindex="-1">API 端点 <a class="header-anchor" href="#api-端点" aria-label="Permalink to “API 端点”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">方法</th><th style="text-align:left;">路径</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">POST</td><td style="text-align:left;"><code>/admin/api/login</code></td><td style="text-align:left;">登录，body <code>{&quot;password&quot;: &quot;...&quot;}</code>，返回 Token</td></tr><tr><td style="text-align:left;">GET</td><td style="text-align:left;"><code>/admin/api/ping</code></td><td style="text-align:left;">存活检测</td></tr><tr><td style="text-align:left;">GET</td><td style="text-align:left;"><code>/admin/api/overview</code></td><td style="text-align:left;">仪表盘数据</td></tr><tr><td style="text-align:left;">GET</td><td style="text-align:left;"><code>/admin/api/status</code></td><td style="text-align:left;">系统状态（CPU / 内存 / 磁盘 / 开机时长）</td></tr><tr><td style="text-align:left;">GET</td><td style="text-align:left;"><code>/admin/api/users</code></td><td style="text-align:left;">用户列表</td></tr><tr><td style="text-align:left;">GET</td><td style="text-align:left;"><code>/admin/api/memory</code></td><td style="text-align:left;">RAG 记忆记录</td></tr><tr><td style="text-align:left;">GET</td><td style="text-align:left;"><code>/admin/api/plugins</code></td><td style="text-align:left;">插件列表</td></tr><tr><td style="text-align:left;">GET</td><td style="text-align:left;"><code>/admin/api/schedule</code></td><td style="text-align:left;">定时任务配置</td></tr><tr><td style="text-align:left;">GET</td><td style="text-align:left;"><code>/admin/api/config</code></td><td style="text-align:left;">机器人配置（脱敏）</td></tr></tbody></table><p>除 <code>login</code> 与 <code>ping</code> 外的接口均需携带请求头 <code>Authorization: Bearer &lt;token&gt;</code>。</p>`,34)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};